// CreateHouseholdCurrency is the resolver for the createHouseholdCurrency field.
func (r *mutationResolver) CreateHouseholdCurrency(ctx context.Context, input ent.CreateHouseholdCurrencyInput) (*ent.HouseholdCurrency, error) {
	householdID := contextkeys.GetHouseholdID(ctx)
	client := ent.FromContext(ctx)

	hc, err := client.HouseholdCurrency.Create().
		SetInput(input).
		SetHouseholdID(householdID).
		Save(ctx)
	if err != nil {
		return nil, err
	}

	existingHCs, err := client.HouseholdCurrency.Query().
		Where(
			householdcurrency.HouseholdIDEQ(householdID),
			householdcurrency.IDNEQ(hc.ID),
		).
		All(ctx)
	if err != nil {
		return nil, err
	}

	if err := r.syncHouseholdRatesForCurrency(ctx, client, householdID, hc, existingHCs); err != nil {
		r.logger.Error("Failed to sync household rates", "error", err)
		return nil, err
	}

	if hc.Important {
		if err := r.backfillSnapshotRatesForCurrency(ctx, client, householdID, hc, existingHCs); err != nil {
			r.logger.Error("Failed to backfill snapshot rates", "error", err)
		}
	}

	return hc, nil
}

// UpdateHouseholdCurrency is the resolver for the updateHouseholdCurrency field.
func (r *mutationResolver) UpdateHouseholdCurrency(ctx context.Context, id int, input ent.UpdateHouseholdCurrencyInput) (*ent.HouseholdCurrency, error) {
	householdID := contextkeys.GetHouseholdID(ctx)
	client := ent.FromContext(ctx)

	old, err := client.HouseholdCurrency.Get(ctx, id)
	if err != nil {
		return nil, err
	}

	hc, err := client.HouseholdCurrency.UpdateOneID(id).
		SetInput(input).
		Save(ctx)
	if err != nil {
		return nil, err
	}

	becameImportant := !old.Important && hc.Important
	if becameImportant {
		existingHCs, err := client.HouseholdCurrency.Query().
			Where(
				householdcurrency.HouseholdIDEQ(householdID),
				householdcurrency.IDNEQ(hc.ID),
			).
			All(ctx)
		if err != nil {
			return nil, err
		}

		if err := r.backfillSnapshotRatesForCurrency(ctx, client, householdID, hc, existingHCs); err != nil {
			r.logger.Error("Failed to backfill snapshot rates", "error", err)
		}
	}

	return hc, nil
}

// DeleteHouseholdCurrency is the resolver for the deleteHouseholdCurrency field.
func (r *mutationResolver) DeleteHouseholdCurrency(ctx context.Context, id int) (*model.DeleteHouseholdCurrencyPayload, error) {
	householdID := contextkeys.GetHouseholdID(ctx)
	client := ent.FromContext(ctx)

	hc, err := client.HouseholdCurrency.Get(ctx, id)
	if err != nil {
		return nil, err
	}

	count, err := client.HouseholdCurrency.Query().
		Where(householdcurrency.HouseholdIDEQ(householdID)).
		Count(ctx)
	if err != nil {
		return nil, err
	}
	if count <= 1 {
		return nil, fmt.Errorf("cannot delete the last currency in a household")
	}

	hasAccounts, err := client.Account.Query().
		Where(
			account.HouseholdIDEQ(householdID),
			account.HasHouseholdCurrencyWith(householdcurrency.ID(hc.ID)),
		).
		Exist(ctx)
	if err != nil {
		return nil, err
	}
	if hasAccounts {
		return nil, fmt.Errorf("cannot delete a currency that is used by accounts")
	}

	hasSubscriptions, err := client.RecurringSubscription.Query().
		Where(
			recurringsubscription.HouseholdIDEQ(householdID),
			recurringsubscription.HasHouseholdCurrencyWith(householdcurrency.ID(hc.ID)),
		).
		Exist(ctx)
	if err != nil {
		return nil, err
	}
	if hasSubscriptions {
		return nil, fmt.Errorf("cannot delete a currency that is used by subscriptions")
	}

	isUserDefault, err := client.UserHousehold.Query().
		Where(
			userhousehold.HouseholdIDEQ(householdID),
			userhousehold.HouseholdCurrencyIDEQ(hc.ID),
		).
		Exist(ctx)
	if err != nil {
		return nil, err
	}
	if isUserDefault {
		return nil, fmt.Errorf("cannot delete a currency that is a user's default display currency")
	}

	_, err = client.HouseholdRate.Delete().
		Where(
			householdrate.HouseholdIDEQ(householdID),
			householdrate.Or(
				householdrate.HasFromCurrencyWith(householdcurrency.ID(hc.ID)),
				householdrate.HasToCurrencyWith(householdcurrency.ID(hc.ID)),
			),
		).
		Exec(ctx)
	if err != nil {
		return nil, err
	}

	snapshots, err := client.Snapshot.Query().All(ctx)
	if err != nil {
		return nil, err
	}
	if len(snapshots) > 0 {
		snapshotIDs := make([]int, len(snapshots))
		for i, s := range snapshots {
			snapshotIDs[i] = s.ID
		}
		_, err = client.SnapshotRate.Delete().
			Where(
				snapshotrate.SnapshotIDIn(snapshotIDs...),
				snapshotrate.Or(
					snapshotrate.HasFromCurrencyWith(householdcurrency.ID(hc.ID)),
					snapshotrate.HasToCurrencyWith(householdcurrency.ID(hc.ID)),
				),
			).
			Exec(ctx)
		if err != nil {
			return nil, err
		}
	}

	if err := client.HouseholdCurrency.DeleteOneID(id).Exec(ctx); err != nil {
		return nil, err
	}

	return &model.DeleteHouseholdCurrencyPayload{DeletedHouseholdCurrencyID: id}, nil
}

// AddHouseholdUser invites a partner into a single-real-user household and
// atomically creates the synthetic joint user, ending in the canonical
// 2-real + 1-synthetic shape. Any other shape is rejected.
func (r *mutationResolver) AddHouseholdUser(ctx context.Context, input model.AddHouseholdUserInput) (*ent.UserHousehold, error) {
	callerID := contextkeys.GetUserID(ctx)
	householdID := contextkeys.GetHouseholdID(ctx)

	ctx, span := r.tracer.Start(ctx, "mutationResolver.AddHouseholdUser",
		trace.WithAttributes(
			attribute.Int("householdID", householdID),
			attribute.Int("callerID", callerID),
		),
	)
	defer span.End()

	client := ent.FromContext(ctx)

	isAdmin, err := client.UserHousehold.Query().
		Where(
			userhousehold.UserIDEQ(callerID),
			userhousehold.HouseholdIDEQ(householdID),
			userhousehold.RoleEQ(userhousehold.RoleAdmin),
		).
		Exist(ctx)
	if err != nil {
		r.logger.Error("Failed to verify household admin", "error", err)
		return nil, err
	}
	if !isAdmin {
		return nil, fmt.Errorf("NOT_HOUSEHOLD_ADMIN")
	}

	h, err := client.Household.Get(ctx, householdID)
	if err != nil {
		return nil, err
	}
	if h.IsDemo {
		return nil, fmt.Errorf("MEMBER_MUTATION_LOCKED_ON_DEMO_HOUSEHOLD")
	}

	if err := userhousehold.RoleValidator(input.Role); err != nil {
		return nil, fmt.Errorf("invalid role")
	}

	householdCtx := context.WithValue(ctx, contextkeys.HouseholdIDKey(), householdID)

	// Bypass needed only for the User lookup: target user is not yet a co-member,
	// so FilterMeOrCoMember would deny the lookup by email. All subsequent
	// queries use householdCtx so FilterByHousehold and FilterAdminOfTargetHousehold
	// continue to apply.
	userLookupCtx := contextkeys.NewPrivacyBypassContext(householdCtx)

	normalizedEmail := strings.ToLower(strings.TrimSpace(input.Email))
	if normalizedEmail == "" {
		return nil, fmt.Errorf("MEMBER_EMAIL_NOT_REGISTERED")
	}
	targetUser, err := client.User.Query().
		Where(user.EmailEQ(normalizedEmail)).
		Only(userLookupCtx)
	if err != nil {
		if ent.IsNotFound(err) {
			return nil, fmt.Errorf("MEMBER_EMAIL_NOT_REGISTERED")
		}
		return nil, err
	}
	if targetUser.IsSynthetic {
		return nil, fmt.Errorf("MEMBER_EMAIL_NOT_REGISTERED")
	}
	span.SetAttributes(attribute.Int("targetUserID", targetUser.ID))

	alreadyMember, err := client.UserHousehold.Query().
		Where(
			userhousehold.UserIDEQ(targetUser.ID),
			userhousehold.HouseholdIDEQ(householdID),
		).
		Exist(householdCtx)
	if err != nil {
		return nil, err
	}
	if alreadyMember {
		return nil, fmt.Errorf("MEMBER_ALREADY_EXISTS")
	}

	realMemberCount, syntheticMemberCount, err := r.countHouseholdMembers(userLookupCtx, householdID)
	if err != nil {
		return nil, err
	}
	if realMemberCount >= 2 {
		return nil, fmt.Errorf("HOUSEHOLD_MAX_REAL_USERS_REACHED")
	}
	if syntheticMemberCount > 0 {
		return nil, fmt.Errorf("HOUSEHOLD_HAS_SYNTHETIC_USER")
	}

	hc, err := client.HouseholdCurrency.Get(householdCtx, input.HouseholdCurrencyID)
	if err != nil || hc.HouseholdID != householdID {
		return nil, fmt.Errorf("invalid household currency")
	}

	partnerUH, err := client.UserHousehold.Create().
		SetUserID(targetUser.ID).
		SetHouseholdID(householdID).
		SetRole(input.Role).
		SetHouseholdCurrencyID(input.HouseholdCurrencyID).
		Save(householdCtx)
	if err != nil {
		r.logger.Error("Failed to add household user", "error", err)
		return nil, fmt.Errorf("failed to add household user: %w", err)
	}

	syntheticUser, err := client.User.Create().
		SetName(syntheticJointUserName).
		SetIsSynthetic(true).
		Save(userLookupCtx)
	if err != nil {
		r.logger.Error("Failed to create synthetic joint user", "error", err)
		return nil, fmt.Errorf("failed to create synthetic joint user: %w", err)
	}
	span.SetAttributes(attribute.Int("syntheticUserID", syntheticUser.ID))

	if _, err := client.UserHousehold.Create().
		SetUserID(syntheticUser.ID).
		SetHouseholdID(householdID).
		SetRole(userhousehold.RoleMember).
		SetHouseholdCurrencyID(input.HouseholdCurrencyID).
		Save(householdCtx); err != nil {
		r.logger.Error("Failed to add synthetic joint UserHousehold", "error", err)
		return nil, fmt.Errorf("failed to add synthetic joint UserHousehold: %w", err)
	}

	return partnerUH, nil
}

// RemoveHouseholdUser removes a real partner from a household. When a
// synthetic joint user exists, it is cascaded out atomically (the synthetic
// user has no meaning in a single-real-user household). Synthetic users
// cannot be removed directly; their lifecycle follows the partner's.
func (r *mutationResolver) RemoveHouseholdUser(ctx context.Context, id int) (*model.RemoveHouseholdUserPayload, error) {
	callerID := contextkeys.GetUserID(ctx)
	householdID := contextkeys.GetHouseholdID(ctx)

	ctx, span := r.tracer.Start(ctx, "mutationResolver.RemoveHouseholdUser",
		trace.WithAttributes(
			attribute.Int("householdID", householdID),
			attribute.Int("callerID", callerID),
			attribute.Int("targetUserHouseholdID", id),
		),
	)
	defer span.End()

	householdCtx := context.WithValue(ctx, contextkeys.HouseholdIDKey(), householdID)
	bypassCtx := contextkeys.NewPrivacyBypassContext(householdCtx)
	client := ent.FromContext(ctx)

	target, err := client.UserHousehold.Get(householdCtx, id)
	if err != nil {
		if ent.IsNotFound(err) {
			return &model.RemoveHouseholdUserPayload{RemovedUserHouseholdID: id}, nil
		}
		return nil, err
	}

	isAdmin, err := client.UserHousehold.Query().
		Where(
			userhousehold.UserIDEQ(callerID),
			userhousehold.HouseholdIDEQ(target.HouseholdID),
			userhousehold.RoleEQ(userhousehold.RoleAdmin),
		).
		Exist(householdCtx)
	if err != nil {
		return nil, err
	}
	if !isAdmin {
		return nil, fmt.Errorf("NOT_HOUSEHOLD_ADMIN")
	}

	if target.UserID == callerID {
		return nil, fmt.Errorf("SELF_REMOVAL_NOT_ALLOWED")
	}

	targetUser, err := client.User.Get(bypassCtx, target.UserID)
	if err != nil {
		return nil, err
	}
	if targetUser.IsSynthetic {
		return nil, fmt.Errorf("SYNTHETIC_USER_REMOVAL_NOT_ALLOWED")
	}

	household, err := client.Household.Get(householdCtx, target.HouseholdID)
	if err != nil {
		return nil, err
	}
	if household.IsDemo {
		return nil, fmt.Errorf("MEMBER_MUTATION_LOCKED_ON_DEMO_HOUSEHOLD")
	}

	if target.Role == userhousehold.RoleAdmin {
		adminCount, err := client.UserHousehold.Query().
			Where(
				userhousehold.HouseholdIDEQ(target.HouseholdID),
				userhousehold.RoleEQ(userhousehold.RoleAdmin),
			).
			Count(householdCtx)
		if err != nil {
			return nil, err
		}
		if adminCount <= 1 {
			return nil, fmt.Errorf("LAST_ADMIN_PROTECTED")
		}
	}

	syntheticUH, err := client.UserHousehold.Query().
		Where(
			userhousehold.HouseholdIDEQ(target.HouseholdID),
			userhousehold.HasUserWith(user.IsSyntheticEQ(true)),
		).
		WithUser().
		First(bypassCtx)
	if err != nil && !ent.IsNotFound(err) {
		return nil, err
	}

	ownerUserIDs := []int{target.UserID}
	if syntheticUH != nil {
		ownerUserIDs = append(ownerUserIDs, syntheticUH.UserID)
	}

	accountCount, err := client.Account.Query().
		Where(
			account.HouseholdIDEQ(target.HouseholdID),
			account.UserIDIn(ownerUserIDs...),
			account.ArchivedEQ(false),
		).
		Count(householdCtx)
	if err != nil {
		return nil, err
	}

	investmentCount, err := client.Investment.Query().
		Where(
			investment.HouseholdIDEQ(target.HouseholdID),
			investment.UserIDIn(ownerUserIDs...),
		).
		Count(householdCtx)
	if err != nil {
		return nil, err
	}

	subscriptionCount, err := client.RecurringSubscription.Query().
		Where(
			recurringsubscription.HouseholdIDEQ(target.HouseholdID),
			recurringsubscription.UserIDIn(ownerUserIDs...),
		).
		Count(householdCtx)
	if err != nil {
		return nil, err
	}

	if accountCount+investmentCount+subscriptionCount > 0 {
		return nil, fmt.Errorf("MEMBER_HAS_OWNED_RECORDS: %d accounts, %d investments, %d subscriptions",
			accountCount, investmentCount, subscriptionCount)
	}

	if err := client.UserHousehold.DeleteOneID(id).Exec(householdCtx); err != nil {
		r.logger.Error("Failed to remove household user", "error", err)
		return nil, fmt.Errorf("failed to remove household user: %w", err)
	}

	if syntheticUH != nil {
		if err := client.UserHousehold.DeleteOneID(syntheticUH.ID).Exec(bypassCtx); err != nil {
			r.logger.Error("Failed to remove synthetic UserHousehold", "error", err)
			return nil, fmt.Errorf("failed to remove synthetic UserHousehold: %w", err)
		}
		if err := client.User.DeleteOneID(syntheticUH.UserID).Exec(bypassCtx); err != nil {
			r.logger.Error("Failed to remove synthetic user", "error", err)
			return nil, fmt.Errorf("failed to remove synthetic user: %w", err)
		}
	}

	return &model.RemoveHouseholdUserPayload{RemovedUserHouseholdID: id}, nil
}

// UpdateHouseholdUserRole is the resolver for the updateHouseholdUserRole field.
func (r *mutationResolver) UpdateHouseholdUserRole(ctx context.Context, id int, role userhousehold.Role) (*ent.UserHousehold, error) {
	callerID := contextkeys.GetUserID(ctx)
	householdID := contextkeys.GetHouseholdID(ctx)

	ctx, span := r.tracer.Start(ctx, "mutationResolver.UpdateHouseholdUserRole",
		trace.WithAttributes(
			attribute.Int("householdID", householdID),
			attribute.Int("callerID", callerID),
			attribute.Int("targetUserHouseholdID", id),
		),
	)
	defer span.End()

	householdCtx := context.WithValue(ctx, contextkeys.HouseholdIDKey(), householdID)
	client := ent.FromContext(ctx)

	target, err := client.UserHousehold.Get(householdCtx, id)
	if err != nil {
		return nil, err
	}

	isAdmin, err := client.UserHousehold.Query().
		Where(
			userhousehold.UserIDEQ(callerID),
			userhousehold.HouseholdIDEQ(target.HouseholdID),
			userhousehold.RoleEQ(userhousehold.RoleAdmin),
		).
		Exist(householdCtx)
	if err != nil {
		return nil, err
	}
	if !isAdmin {
		return nil, fmt.Errorf("NOT_HOUSEHOLD_ADMIN")
	}

	household, err := client.Household.Get(householdCtx, target.HouseholdID)
	if err != nil {
		return nil, err
	}
	if household.IsDemo {
		return nil, fmt.Errorf("MEMBER_MUTATION_LOCKED_ON_DEMO_HOUSEHOLD")
	}

	bypassCtx := contextkeys.NewPrivacyBypassContext(householdCtx)
	targetUser, err := client.User.Get(bypassCtx, target.UserID)
	if err != nil {
		return nil, err
	}
	if targetUser.IsSynthetic {
		return nil, fmt.Errorf("SYNTHETIC_USER_ROLE_CHANGE_NOT_ALLOWED")
	}

	if target.Role == role {
		return target, nil
	}

	if target.Role == userhousehold.RoleAdmin && role == userhousehold.RoleMember {
		adminCount, err := client.UserHousehold.Query().
			Where(
				userhousehold.HouseholdIDEQ(target.HouseholdID),
				userhousehold.RoleEQ(userhousehold.RoleAdmin),
			).
			Count(householdCtx)
		if err != nil {
			return nil, err
		}
		if adminCount <= 1 {
			return nil, fmt.Errorf("LAST_ADMIN_PROTECTED")
		}
	}

	updated, err := client.UserHousehold.UpdateOneID(id).
		SetRole(role).
		Save(householdCtx)
	if err != nil {
		r.logger.Error("Failed to update household user role", "error", err)
		return nil, fmt.Errorf("failed to update household user role: %w", err)
	}

	return updated, nil
}

// CreateSnapshot is the resolver for the createSnapshot field.
func (r *mutationResolver) CreateSnapshot(ctx context.Context, input ent.CreateSnapshotInput) (*ent.SnapshotEdge, error) {
	userID := contextkeys.GetUserID(ctx)
	householdID := contextkeys.GetHouseholdID(ctx)

	ctx, span := r.tracer.Start(ctx, "mutationResolver.CreateSnapshot",
		trace.WithAttributes(
			attribute.Int("householdID", householdID),
			attribute.Int("userID", userID),
		),
	)
	defer span.End()

	client := ent.FromContext(ctx)

	accounts, err := client.Account.Query().
		Where(account.ArchivedEQ(false)).
		WithHouseholdCurrency().
		All(ctx)
	if err != nil {
		r.logger.Error("Failed to fetch accounts", "error", err)
		return nil, err
	}

	snap, err := client.Snapshot.Create().
		SetHouseholdID(householdID).
		SetInput(input).
		Save(ctx)
	if err != nil {
		r.logger.Error("Failed to create snapshot", "error", err)
		return nil, err
	}

	type entryKey struct {
		UserID              int
		HouseholdCurrencyID int
	}
	type entryValues struct {
		Liquidity  decimal.Decimal
		Investment decimal.Decimal
		Property   decimal.Decimal
		Receivable decimal.Decimal
		Liability  decimal.Decimal
	}

	grouped := make(map[entryKey]*entryValues)
	zero := decimal.NewFromInt(0)

	for _, acc := range accounts {
		key := entryKey{UserID: acc.UserID, HouseholdCurrencyID: acc.Edges.HouseholdCurrency.ID}
		vals, ok := grouped[key]
		if !ok {
			vals = &entryValues{
				Liquidity:  zero,
				Investment: zero,
				Property:   zero,
				Receivable: zero,
				Liability:  zero,
			}
			grouped[key] = vals
		}

		switch acc.Type {
		case account.TypeLiquidity:
			vals.Liquidity = vals.Liquidity.Add(acc.Value)
		case account.TypeInvestment:
			vals.Investment = vals.Investment.Add(acc.Value)
		case account.TypeProperty:
			vals.Property = vals.Property.Add(acc.Value)
		case account.TypeReceivable:
			vals.Receivable = vals.Receivable.Add(acc.Value)
		case account.TypeLiability:
			vals.Liability = vals.Liability.Add(acc.Value)
		}
	}

	builders := make([]*ent.SnapshotEntryCreate, 0, len(grouped))
	for key, vals := range grouped {
		builders = append(builders, client.SnapshotEntry.Create().
			SetSnapshotID(snap.ID).
			SetHouseholdID(householdID).
			SetUserID(key.UserID).
			SetHouseholdCurrencyID(key.HouseholdCurrencyID).
			SetLiquidity(vals.Liquidity).
			SetInvestment(vals.Investment).
			SetProperty(vals.Property).
			SetReceivable(vals.Receivable).
			SetLiability(vals.Liability),
		)
	}

	if len(builders) > 0 {
		if _, err := client.SnapshotEntry.CreateBulk(builders...).Save(ctx); err != nil {
			r.logger.Error("Failed to create snapshot entries", "error", err)
			return nil, err
		}
	}

	householdRates, err := client.HouseholdRate.Query().All(ctx)
	if err != nil {
		r.logger.Error("Failed to fetch household rates", "error", err)
		return nil, err
	}

	if len(householdRates) > 0 {
		rateBuilders := make([]*ent.SnapshotRateCreate, 0, len(householdRates))
		for _, hr := range householdRates {
			rateBuilders = append(rateBuilders, client.SnapshotRate.Create().
				SetHouseholdID(householdID).
				SetSnapshotID(snap.ID).
				SetFromCurrencyID(hr.FromHouseholdCurrencyID).
				SetToCurrencyID(hr.ToHouseholdCurrencyID).
				SetRate(hr.Rate),
			)
		}
		if _, err := client.SnapshotRate.CreateBulk(rateBuilders...).Save(ctx); err != nil {
			r.logger.Error("Failed to create snapshot rates", "error", err)
			return nil, err
		}
	}

	return &ent.SnapshotEdge{
		Node:   snap,
		Cursor: gqlutil.EncodeCursor(snap.ID),
	}, nil
}

// UpdateSnapshot is the resolver for the updateSnapshot field.
func (r *mutationResolver) UpdateSnapshot(ctx context.Context, id int, input ent.UpdateSnapshotInput) (*ent.SnapshotEdge, error) {
	userID := contextkeys.GetUserID(ctx)
	householdID := contextkeys.GetHouseholdID(ctx)

	ctx, span := r.tracer.Start(ctx, "mutationResolver.UpdateSnapshot",
		trace.WithAttributes(
			attribute.Int("householdID", householdID),
			attribute.Int("userID", userID),
		),
	)
	defer span.End()

	client := ent.FromContext(ctx)

	updated, err := client.Snapshot.UpdateOneID(id).SetInput(input).Save(ctx)
	if err != nil {
		r.logger.Error("Failed to update snapshot", "error", err)
		return nil, err
	}

	return &ent.SnapshotEdge{
		Node:   updated,
		Cursor: gqlutil.EncodeCursor(updated.ID),
	}, nil
}

// DeleteSnapshot is the resolver for the deleteSnapshot field.
func (r *mutationResolver) DeleteSnapshot(ctx context.Context, id int) (*model.DeleteSnapshotPayload, error) {
	userID := contextkeys.GetUserID(ctx)
	householdID := contextkeys.GetHouseholdID(ctx)

	ctx, span := r.tracer.Start(ctx, "mutationResolver.DeleteSnapshot",
		trace.WithAttributes(
			attribute.Int("householdID", householdID),
			attribute.Int("userID", userID),
		),
	)
	defer span.End()

	client := ent.FromContext(ctx)

	if err := client.Snapshot.DeleteOneID(id).Exec(ctx); err != nil {
		r.logger.Error("Failed to delete snapshot", "error", err)
		return nil, err
	}

	return &model.DeleteSnapshotPayload{DeletedSnapshotID: id}, nil
}

// Refresh is the resolver for the refresh field.
func (r *mutationResolver) Refresh(ctx context.Context) (bool, error) {
	userID := contextkeys.GetUserID(ctx)
	householdID := contextkeys.GetHouseholdID(ctx)

	ctx, span := r.tracer.Start(ctx, "mutationResolver.Refresh",
		trace.WithAttributes(
			attribute.Int("householdID", householdID),
			attribute.Int("userID", userID),
		),
	)
	defer span.End()

	client := ent.FromContext(ctx)

	// Fetch all investments for the household
	investments, err := client.Investment.Query().
		All(ctx)
	if err != nil {
		r.logger.Error("Failed to fetch investments", "error", err)
		return false, err
	}

	if len(investments) == 0 {
		return true, nil
	}

	// Group investments by type (stock vs crypto)
	stockInvestments := lo.GroupBy(
		lo.Filter(investments, func(inv *ent.Investment, _ int) bool {
			return inv.Type == investment.TypeStock
		}),
		func(inv *ent.Investment) string {
			return strings.ToUpper(inv.Symbol)
		},
	)

	cryptoInvestments := lo.GroupBy(
		lo.Filter(investments, func(inv *ent.Investment, _ int) bool {
			return inv.Type == investment.TypeCrypto
		}),
		func(inv *ent.Investment) string {
			return strings.ToUpper(inv.Symbol)
		},
	)

	stockSymbols := lo.Keys(stockInvestments)
	cryptoSymbols := lo.Keys(cryptoInvestments)

	// Batch fetch stock quotes
	if len(stockSymbols) > 0 {
		quotes, err := r.stockClient.Quotes(ctx, stockSymbols)
		if err != nil {
			r.logger.Error("Failed to fetch stock quotes", "error", err)
			return false, err
		}

		// Update investments with new quotes
		for symbol, invList := range stockInvestments {
			quote, ok := quotes[symbol]
			if !ok {
				r.logger.Error("Stock quote not found for symbol", "symbol", symbol)
				continue
			}

			for _, inv := range invList {
				err := client.Investment.UpdateOneID(inv.ID).
					SetQuote(quote.CurrentPrice).
					Exec(ctx)
				if err != nil {
					r.logger.Error("Failed to update investment quote", "error", err, "investmentID", inv.ID)
					return false, err
				}
			}
		}
	}

	// Batch fetch crypto quotes
	if len(cryptoSymbols) > 0 {
		quotes, err := r.cryptoClient.Quotes(ctx, cryptoSymbols)
		if err != nil {
			r.logger.Error("Failed to fetch crypto quotes", "error", err)
			return false, err
		}

		// Update investments with new quotes
		for symbol, invList := range cryptoInvestments {
			quote, ok := quotes[symbol]
			if !ok {
				r.logger.Error("Crypto quote not found for symbol", "symbol", symbol)
				continue
			}

			for _, inv := range invList {
				err := client.Investment.UpdateOneID(inv.ID).
					SetQuote(quote.CurrentPrice).
					Exec(ctx)
				if err != nil {
					r.logger.Error("Failed to update investment quote", "error", err, "investmentID", inv.ID)
					return false, err
				}
			}
		}
	}

	if err := r.refreshHouseholdRates(ctx, client, householdID); err != nil {
		r.logger.Error("Failed to refresh household rates", "error", err)
		return false, err
	}

	return true, nil
}

// Mutation returns MutationResolver implementation.
func (r *Resolver) Mutation() MutationResolver { return &mutationResolver{r} }

type mutationResolver struct{ *Resolver }
